package com.example.starter.scene.model;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.util.List;

/**
 * Planning Scene 服务对外 HTTP 接口使用的请求/响应模型集合。
 */
public final class SceneApi {

    private SceneApi() {
    }

    /** 批量操作类型。 */
    public enum OperationType {
        /** 新增或修改世界中的碰撞对象。 */
        OBJECT_UPSERT,
        /** 删除碰撞对象（附着中的对象会先自动 detach）。 */
        OBJECT_DELETE,
        /** 重命名碰撞对象（附着关系同步迁移到新 ID）。 */
        OBJECT_RENAME,
        /** 更新单个关节角度（单位：弧度，必须位于关节上下限内）。 */
        JOINT_UPDATE,
        /** 将世界中的对象附着到指定机器人 Link。 */
        ATTACH,
        /** 将附着中的对象释放回世界。 */
        DETACH
    }

    /** 位姿：平移单位米，姿态为四元数 (x,y,z,w)；frameId 为存在的坐标系（机器人 Link 或 world）。 */
    public record PoseData(
            @NotBlank String frameId,
            double x,
            double y,
            double z,
            double qx,
            double qy,
            double qz,
            double qw) {
    }

    /** 机器人模型中的关节定义：name 唯一，角度（弧度）取值范围 [min,max]。 */
    public record JointSpec(
            @NotBlank String name,
            double min,
            double max,
            double initialValue) {
    }

    /** 机器人模型初始化请求：Link 名集合、关节定义与初始机器人姿态。 */
    public record RobotModelRequest(
            @NotEmpty List<@NotBlank String> links,
            @NotEmpty @Valid List<JointSpec> joints,
            @Valid PoseData initialPose) {
    }

    /** 单个批量操作；不同 type 使用其中不同字段。 */
    public record OperationRequest(
            @NotNull OperationType type,
            String objectId,
            String newObjectId,
            String frameId,
            String shape,
            Double sizeX,
            Double sizeY,
            Double sizeZ,
            Double x,
            Double y,
            Double z,
            Double qx,
            Double qy,
            Double qz,
            Double qw,
            String jointName,
            Double jointValue,
            String linkName) {
    }

    /** 一次场景修改请求；requestId 为幂等键，expectedVersion 为乐观版本号。 */
    public record ChangeRequest(
            @NotBlank String requestId,
            @PositiveOrZero long expectedVersion,
            @NotEmpty @Valid List<OperationRequest> operations,
            @Valid PoseData robotPose) {
    }

    /** 碰撞对象快照；attachedLink 为 null 表示位于世界，非 null 表示附着在该机器人 Link 上。 */
    public record ObjectSnapshot(
            String objectId,
            String frameId,
            String shape,
            double sizeX,
            double sizeY,
            double sizeZ,
            double x,
            double y,
            double z,
            double qx,
            double qy,
            double qz,
            double qw,
            String attachedLink) {
    }

    /** 关节状态快照，value 单位弧度。 */
    public record JointSnapshot(String name, double value) {
    }

    /** 某一版本的不可变 Planning Scene 快照。 */
    public record SnapshotResponse(
            long version,
            PoseData robotPose,
            List<JointSnapshot> joints,
            List<ObjectSnapshot> objects) {
    }

    /** 修改提交结果；replayed=true 表示命中幂等重放，未产生新版本。 */
    public record CommitResult(
            String requestId,
            long version,
            boolean committed,
            boolean replayed) {
    }
}

package com.example.starter.scene.exception;

import java.util.List;

/**
 * 请求中的操作违反业务规则（数值非法、引用不存在等），整批回滚，对应 HTTP 400。
 */
public class SceneValidationException extends RuntimeException {

    private final int operationIndex;

    public SceneValidationException(String message) {
        this(-1, message);
    }

    public SceneValidationException(int operationIndex, String message) {
        super(message);
        this.operationIndex = operationIndex;
    }

    public int getOperationIndex() {
        return operationIndex;
    }

    /** 用于批量静态校验时聚合错误，当前逐个抛出即可。 */
    public static SceneValidationException at(int index, String message) {
        return new SceneValidationException(index, message);
    }

    public static List<String> noDetails() {
        return List.of();
    }
}

package com.example.starter.scene.exception;

import java.util.List;

/**
 * 版本冲突或幂等键冲突，对应 HTTP 409。
 */
public class SceneConflictException extends RuntimeException {

    private final String code;
    private final long expectedVersion;
    private final long currentVersion;
    private final List<String> changedObjectIds;
    private final List<String> changedJointNames;
    private final boolean robotPoseChanged;

    public SceneConflictException(String code, String message, long expectedVersion, long currentVersion,
                                  List<String> changedObjectIds, List<String> changedJointNames,
                                  boolean robotPoseChanged) {
        super(message);
        this.code = code;
        this.expectedVersion = expectedVersion;
        this.currentVersion = currentVersion;
        this.changedObjectIds = changedObjectIds;
        this.changedJointNames = changedJointNames;
        this.robotPoseChanged = robotPoseChanged;
    }

    public String getCode() {
        return code;
    }

    public long getExpectedVersion() {
        return expectedVersion;
    }

    public long getCurrentVersion() {
        return currentVersion;
    }

    public List<String> getChangedObjectIds() {
        return changedObjectIds;
    }

    public List<String> getChangedJointNames() {
        return changedJointNames;
    }

    public boolean isRobotPoseChanged() {
        return robotPoseChanged;
    }
}

package com.example.starter.scene.exception;

/** 请求的历史版本不存在，对应 HTTP 404。 */
public class SceneNotFoundException extends RuntimeException {

    public SceneNotFoundException(String message) {
        super(message);
    }
}

