        service.apply(new SceneApi.ChangeRequest("a-1", 0,
                List.of(upsert("box_a", "world", 1, 0, 0), joint("joint_a", 0.4)), null));
        // 客户端 B 基于版本 0 新增 box_b、更新 joint_b
